INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'empire', 'n.', '/ˈempaɪə(r)/', '帝国', 'The Grand Canal became the lifeline of the whole empire.', '大运河成了整个帝国的命脉。', 'Delving into History', 1, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the whole empire', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'economy', 'n.', '/ɪˈkɒnəmi/', '经济;经济情况', 'The canal helped to promote the economy of the empire.', '运河帮助促进了帝国的经济。', 'Delving into History', 2, 0, 'senior', 'wordlist', 'elective4', 'U3', 'promote the economy', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'expansion', 'n.', '/ɪkˈspænʃn/', '扩张;扩展', 'The expansion of the railway slowly replaced the old canal.', '铁路的扩展慢慢取代了古老的运河。', 'Delving into History', 3, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the expansion of trade', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'income', 'n.', '/ˈɪnkʌm/', '收入;收益', 'Salt became an important source of income during the Ming dynasty.', '盐在明朝成了重要的收入来源。', 'Delving into History', 4, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a source of income', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'route', 'n.', '/ruːt/', '路线;固定线路', 'The Silk Road was a famous trade route between East and West.', '丝绸之路是连接东西方的著名贸易路线。', 'Delving into History', 5, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a trade route', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'port', 'n.', '/pɔːt/', '港口;港口城市', 'Many goods left from the busy port cities along the coast.', '许多货物从沿海繁忙的港口城市运出。', 'Delving into History', 6, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a busy port', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'thrive', 'v.', '/θraɪv/', '兴旺;繁荣;蓬勃发展', 'Suzhou grew to thrive as a centre of trade along the canal.', '苏州发展成运河沿线繁荣的贸易中心。', 'Delving into History', 7, 0, 'senior', 'wordlist', 'elective4', 'U3', 'thrive on trade', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'prove', 'v.', '/pruːv/', '证明;证实;结果是', 'The canal proved a powerful tool for moving grain north.', '运河被证明是向北运粮的有力工具。', 'Delving into History', 8, 0, 'senior', 'wordlist', 'elective4', 'U3', 'prove useful', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'operate', 'v.', '/ˈɒpəreɪt/', '操作;运转;运营', 'Thousands of soldiers were needed to operate the canal boats.', '需要数千名士兵来驾驶运河上的船只。', 'Delving into History', 9, 0, 'senior', 'wordlist', 'elective4', 'U3', 'operate the boats', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'aim', 'n.', '/eɪm/', '目的;目标', 'The main aim of the project is to move water to dry regions.', '这一工程的主要目标是把水调往干旱地区。', 'Delving into History', 10, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the main aim', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'divert', 'v.', '/daɪˈvɜːt/', '使转向;转移;改道', 'The project will divert water from the south to the north.', '这项工程将把南方的水调往北方。', 'Delving into History', 11, 0, 'senior', 'wordlist', 'elective4', 'U3', 'divert water', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'arid', 'adj.', '/ˈærɪd/', '干旱的;干燥的', 'Water is carried to the arid regions of the north every year.', '每年都有水被输送到北方干旱的地区。', 'Delving into History', 12, 0, 'senior', 'wordlist', 'elective4', 'U3', 'an arid region', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'legendary', 'adj.', '/ˈledʒəndri/', '享有盛名的;传奇的', 'The legendary Silk Road linked China with distant lands.', '传奇的丝绸之路把中国与遥远的国度连接起来。', 'Delving into History', 13, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the legendary Silk Road', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gateway', 'n.', '/ˈɡeɪtweɪ/', '门户;通道', 'Istanbul was seen as the gateway to Europe on the Silk Road.', '伊斯坦布尔被视为丝绸之路上通往欧洲的门户。', 'Delving into History', 14, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the gateway to Europe', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'boom', 'v.', '/buːm/', '迅速发展;激增;繁荣', 'The trade in silk boomed along the entire length of the road.', '丝绸贸易沿整条道路迅速发展。', 'Delving into History', 15, 0, 'senior', 'wordlist', 'elective4', 'U3', 'trade boomed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'commodity', 'n.', '/kəˈmɒdəti/', '商品;货物', 'Silk was the most valuable commodity traded from China.', '丝绸是中国出口的最珍贵的商品。', 'Delving into History', 16, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a valuable commodity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'complex', 'adj.', '/ˈkɒmpleks/', '复杂的;难懂的', 'The trade routes grew into a complex network of paths.', '这些贸易路线发展成一张复杂的路网。', 'Delving into History', 17, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a complex network', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pave', 'v.', '/peɪv/', '铺(路);为……创造条件', 'Zhang Qian''s journeys paved the way for trade with the West.', '张骞的出使为同西方的贸易铺平了道路。', 'Delving into History', 18, 0, 'senior', 'wordlist', 'elective4', 'U3', 'pave the way', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'diplomatic', 'adj.', '/ˌdɪpləˈmætɪk/', '外交的', 'His missions opened the way for diplomatic exchanges between states.', '他的出使为各国间的外交往来开辟了道路。', 'Delving into History', 19, 0, 'senior', 'wordlist', 'elective4', 'U3', 'diplomatic exchanges', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'commercial', 'adj.', '/kəˈmɜːʃl/', '商业的;贸易的', 'The Silk Road encouraged commercial exchanges across many lands.', '丝绸之路促进了许多国家之间的商业往来。', 'Delving into History', 20, 0, 'senior', 'wordlist', 'elective4', 'U3', 'commercial exchanges', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'kingdom', 'n.', '/ˈkɪŋdəm/', '王国', 'Traders carried goods between the Middle Kingdom and the West.', '商人在中国与西方之间运送货物。', 'Delving into History', 21, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the Middle Kingdom', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'religious', 'adj.', '/rɪˈlɪdʒəs/', '宗教的;宗教信仰的', 'The road also became a channel for religious thought.', '这条道路也成了宗教思想传播的通道。', 'Delving into History', 22, 0, 'senior', 'wordlist', 'elective4', 'U3', 'religious thought', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'efficient', 'adj.', '/ɪˈfɪʃnt/', '高效的;有功效的', 'The Silk Road was an efficient way to spread new ideas.', '丝绸之路是传播新思想的高效途径。', 'Delving into History', 23, 0, 'senior', 'wordlist', 'elective4', 'U3', 'an efficient way', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'version', 'n.', '/ˈvɜːʃn/', '版本;变体;型式', 'The Silk Road was a kind of ancient version of the information highway.', '丝绸之路是信息高速公路的一种古代版本。', 'Delving into History', 24, 0, 'senior', 'wordlist', 'elective4', 'U3', 'an ancient version', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'porcelain', 'n.', '/ˈpɔːsəlɪn/', '瓷;瓷器', 'The Chinese traded fine porcelain, tea and gold with the West.', '中国人用精美的瓷器、茶叶和黄金同西方交易。', 'Delving into History', 25, 0, 'senior', 'wordlist', 'elective4', 'U3', 'fine porcelain', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'craft', 'n.', '/krɑːft/', '手艺;工艺', 'Asian skills and crafts were shared along the Silk Road.', '亚洲的技艺和工艺沿丝绸之路得到分享。', 'Delving into History', 26, 0, 'senior', 'wordlist', 'elective4', 'U3', 'skills and crafts', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'spin', 'v.', '/spɪn/', '纺(线);快速旋转', 'The skill of spinning silk thread spread westward along the road.', '纺丝的技艺沿这条路向西传播。', 'Delving into History', 27, 0, 'senior', 'wordlist', 'elective4', 'U3', 'spin silk', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'iron', 'n.', '/ˈaɪən/', '铁', 'Iron casting was one of the crafts introduced to the West.', '铸铁是传入西方的工艺之一。', 'Delving into History', 28, 0, 'senior', 'wordlist', 'elective4', 'U3', 'cast iron', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cast', 'v.', '/kɑːst/', '浇铸;铸造', 'Workers learned to cast iron and make strong tools.', '工人们学会了铸铁并制作坚固的工具。', 'Delving into History', 29, 0, 'senior', 'wordlist', 'elective4', 'U3', 'cast iron', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'performance', 'n.', '/pəˈfɔːməns/', '表演;演出', 'Music and dance performances from Central Asia were popular in China.', '来自中亚的音乐舞蹈表演在中国很受欢迎。', 'Delving into History', 30, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a music performance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'feature', 'v.', '/ˈfiːtʃə(r)/', '以……为特色;由……主演', 'The shows often featured dancers and musicians in colourful masks.', '这些演出常以戴着彩色面具的舞者和乐师为特色。', 'Delving into History', 31, 0, 'senior', 'wordlist', 'elective4', 'U3', 'feature dancers', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'agriculture', 'n.', '/ˈæɡrɪkʌltʃə(r)/', '农业;农艺', 'In agriculture, grapes and walnuts were brought to China from the west.', '在农业方面,葡萄和核桃从西方传入中国。', 'Delving into History', 32, 0, 'senior', 'wordlist', 'elective4', 'U3', 'in agriculture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'maritime', 'adj.', '/ˈmærɪtaɪm/', '海的;海运的', 'Scholars call the sea routes the Maritime Silk Road.', '学者把这些海上路线称为海上丝绸之路。', 'Delving into History', 33, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the Maritime Silk Road', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'coastal', 'adj.', '/ˈkəʊstl/', '沿海的;靠近海岸的', 'Ships left the coastal ports of southeast China and sailed far away.', '船只从中国东南沿海的港口出发,航行到远方。', 'Delving into History', 34, 0, 'senior', 'wordlist', 'elective4', 'U3', 'coastal ports', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'strait', 'n.', '/streɪt/', '海峡', 'The ships sailed through the Strait of Malacca on their way west.', '船只在西行途中穿过马六甲海峡。', 'Delving into History', 35, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the Strait of Malacca', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'destination', 'n.', '/ˌdestɪˈneɪʃn/', '目的地;终点', 'The boats reached distant destinations as far away as India.', '这些船只到达了远至印度的目的地。', 'Delving into History', 36, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a distant destination', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'peninsula', 'n.', '/pəˈnɪnsjələ/', '半岛', 'The sea route reached as far as the Indian Peninsula.', '这条海路远达印度半岛。', 'Delving into History', 37, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the Indian Peninsula', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gain', 'v.', '/ɡeɪn/', '获得;取得', 'Countries along the routes gained much more than material goods.', '沿线国家获得的远不止物质货物。', 'Delving into History', 38, 0, 'senior', 'wordlist', 'elective4', 'U3', 'gain much', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'material', 'adj.', '/məˈtɪəriəl/', '物质的;实际的', 'The Silk Road brought more than just material goods to the world.', '丝绸之路给世界带来的不只是物质货物。', 'Delving into History', 39, 0, 'senior', 'wordlist', 'elective4', 'U3', 'material goods', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'invaluable', 'adj.', '/ɪnˈvæljuəbl/', '极宝贵的;极有用的', 'The road brought about an invaluable exchange of culture.', '这条路带来了极其宝贵的文化交流。', 'Delving into History', 40, 0, 'senior', 'wordlist', 'elective4', 'U3', 'an invaluable exchange', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lifeline', 'n.', '/ˈlaɪflaɪn/', '命脉;生命线', 'The Grand Canal became the economic lifeline of the empire.', '大运河成了帝国的经济命脉。', 'Delving into History', 41, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the economic lifeline', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'large-scale', 'adj.', '/ˌlɑːdʒ ˈskeɪl/', '大规模的;大范围的', 'Never before had such a large-scale canal project been attempted.', '此前从未尝试过如此大规模的运河工程。', 'Delving into History', 42, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a large-scale project', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cotton', 'n.', '/ˈkɒtn/', '棉布;棉花', 'Goods sent from the north included cotton, wool and coal.', '从北方运来的货物包括棉布、毛料和煤。', 'Delving into History', 43, 0, 'senior', 'wordlist', 'elective4', 'U3', 'cotton and wool', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'wool', 'n.', '/wʊl/', '毛料;羊毛', 'Wool was carried south while grain was carried north.', '毛料被运往南方,而粮食被运往北方。', 'Delving into History', 44, 0, 'senior', 'wordlist', 'elective4', 'U3', 'wool and cotton', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'barge', 'n.', '/bɑːdʒ/', '驳船(平底货船)', 'Thousands of government barges travelled along this route each year.', '每年有数千艘官府驳船沿这条线路航行。', 'Delving into History', 45, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a government barge', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'chief', 'adj.', '/tʃiːf/', '最重要的;首要的', 'Many port cities thrived, chief among them Suzhou.', '许多港口城市繁荣起来,其中以苏州为首。', 'Delving into History', 46, 0, 'senior', 'wordlist', 'elective4', 'U3', 'chief among them', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'restrict', 'v.', '/rɪˈstrɪkt/', '限制;限定', 'The routes were not restricted to land but also crossed the sea.', '这些路线不限于陆地,也跨越海洋。', 'Delving into History', 47, 0, 'senior', 'wordlist', 'elective4', 'U3', 'be restricted to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'two-way', 'adj.', '/ˌtuː ˈweɪ/', '双向的', 'The routes became a two-way movement of trade and ideas.', '这些路线成了贸易与思想的双向流动。', 'Delving into History', 48, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a two-way movement', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u3.01', '①否定/半否定副词置于句首的部分倒装(Never/Hardly/No sooner/Not until/Seldom/Not only…)', 'A2', 12, '上外版选择性必修第四册 U3 — 当 never, never before, hardly…when, no sooner…than, not until, seldom, rarely, little, not only, on no account, nowhere 等否定或半否定词语置于句首时,主句用部分倒装:把助动词/情态动词/be 提到主语之前(do/does/did + 主语 + 动词原形;或 had/have + 主语 + 过去分词)。', 1, 'elective4', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u3.02', '②“Only + 状语”置于句首的部分倒装(Only then / Only when / Only by / Only after…)', 'A2', 12, '上外版选择性必修第四册 U3 — 当 “only + 副词/介词短语/状语从句” 置于句首时,主句(而非从句)用部分倒装:把助动词/情态动词提到主语之前,如 Only then did people realise…;Only by working together could they finish it。', 2, 'elective4', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u3.03', '③“so/such…that”倒装 与 虚拟条件句的省略倒装(Had/Were/Should…)', 'A2', 12, '上外版选择性必修第四册 U3 — ① So + 形容词/副词 或 Such + 名词 置于句首时,主句部分倒装(So important was the canal that…;Such was the fame that…)。② 虚拟条件句省略 if 时,把 had/were/should 提到主语前构成倒装:Had I known…(=If I had known);Were it not for…;Should you…。', 3, 'elective4', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Never before ____ such a long canal been dug by human hands.', 'had', 'did', 'have', 'was', 'A', '否定词 Never before 置于句首,过去完成被动用 had 提前(had…been dug)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Never ____ so clearly why people study the past.', 'I had understood', 'had I understood', 'did I understood', 'I understood', 'B', 'Never 置于句首要部分倒装,助动词 had 提到主语 I 之前。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Not until the railway was built ____ the Grand Canal lose its importance.', 'had', 'was', 'did', 'does', 'C', 'Not until 状语前置,主句倒装用 did + 主语 + 动词原形 lose。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Not until he read the old records ____ the truth about the canal.', 'the scholar learned', 'the scholar did learn', 'did the scholar learned', 'did the scholar learn', 'D', 'Not until 前置,主句倒装 did + 主语 + 原形 learn。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Hardly ____ the tour of the Forbidden City begun when it started to rain.', 'had', 'did', 'was', 'has', 'A', 'Hardly…when 结构,前半用过去完成,倒装 had 提到主语前。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'No sooner ____ the gates opened than thousands of visitors poured in.', 'did', 'had', 'were', 'have', 'B', 'No sooner…than 结构,前句用过去完成倒装,had 提前。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Seldom ____ such a well-preserved ancient site.', 'we have seen', 'did we saw', 'have we seen', 'we saw', 'C', 'Seldom 置于句首,现在完成倒装,have 提到主语 we 之前。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Rarely ____ a canal played such a key role in a country’s history.', 'did', 'have', 'was', 'has', 'D', 'Rarely 句首倒装,主语 a canal 为单数,用 has played。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Little ____ how much the canal would change their lives.', 'did the villagers know', 'the villagers knew', 'did the villagers knew', 'the villagers did know', 'A', 'Little 表否定置于句首,倒装 did + 主语 + 原形 know。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Not only ____ the Grand Canal carry grain, but it also spread new ideas.', 'had', 'did', 'was', 'does', 'B', 'Not only 置于句首,部分倒装 did + 主语 + 原形 carry。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Not only ____ goods along the route, but they also exchanged customs.', 'traders carried', 'traders did carry', 'did traders carry', 'did traders carried', 'C', 'Not only 句首部分倒装,did + 主语 + 原形 carry。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'On no account ____ touch the priceless relics in the hall.', 'visitors should', 'visitors must to', 'should visitors to', 'should visitors', 'D', 'On no account 表否定置于句首,倒装 should + 主语 + 原形 touch。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Nowhere else in China ____ so many old canal towns.', 'can you find', 'you can find', 'can you found', 'you could finding', 'A', 'Nowhere 表否定地点置于句首,倒装 can + 主语 + 原形 find。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Not for a moment ____ that the old city walls would be saved.', 'she doubted', 'did she doubt', 'she did doubt', 'did she doubted', 'B', 'Not for a moment 表否定置于句首,倒装 did + 主语 + 原形 doubt。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'By no means ____ an easy task to keep the canal flowing.', 'it was', 'it is', 'was it', 'were it', 'C', 'By no means 表否定置于句首,系动词 was 提到主语 it 之前。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Never before ____ a project so large been attempted in the region.', 'did', 'has', 'was', 'had', 'D', 'Never before + 过去完成被动,倒装 had 提前(had…been attempted)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Hardly ____ the emperor announced the plan when work began at once.', 'had', 'did', 'was', 'does', 'A', 'Hardly…when,前句用过去完成倒装,had 提前。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Seldom ____ the value of protecting these historic sites.', 'we question', 'do we question', 'did we questioned', 'we do question', 'B', 'Seldom 置于句首,一般现在倒装 do + 主语 + 原形 question。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'Not until dusk ____ exploring the ruins of the old town.', 'the students stopped', 'the students did stop', 'did the students stop', 'did the students stopped', 'C', 'Not until 前置,主句倒装 did + 主语 + 原形 stop。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.01'), 'No sooner ____ off the boat than the guide began the tour.', 'we had stepped', 'did we step', 'we stepped', 'had we stepped', 'D', 'No sooner…than,过去完成倒装,had 提到主语 we 之前。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only then ____ how important the canal had been to the empire.', 'did people realise', 'people realised', 'people did realise', 'did people realised', 'A', 'Only then 置于句首,主句部分倒装 did + 主语 + 原形 realise。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only after years of digging ____ the two rivers finally linked.', 'did', 'were', 'was', 'had', 'B', 'Only after… 状语前置,主句倒装;rivers 复数被动用 were…linked。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only in this way ____ protect the ancient site for future generations.', 'we can', 'could we to', 'can we', 'we could', 'C', 'Only in this way 置于句首,倒装 can + 主语 we + 原形 protect。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only when the war ended ____ the canal again.', 'the emperor repaired', 'the emperor did repair', 'did the emperor repaired', 'did the emperor repair', 'D', 'Only when… 置于句首,主句倒装 did + 主语 + 原形 repair。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only by studying history ____ truly understand the present.', 'can we', 'we can', 'we could to', 'could we to', 'A', 'Only by… 置于句首,倒装 can + 主语 we + 原形 understand。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only after Marco Polo returned ____ about the wonders of the East.', 'Europe learned', 'did Europe learn', 'Europe did learn', 'did Europe learned', 'B', 'Only after… 置于句首,主句倒装 did + 主语 + 原形 learn。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only then ____ the real purpose of the Grand Canal.', 'historians understood', 'historians did understand', 'did historians understand', 'did historians understood', 'C', 'Only then 置于句首,倒装 did + 主语 + 原形 understand。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only with careful planning ____ the old buildings be saved.', 'did', 'were', 'had', 'could', 'D', 'Only with… 置于句首,倒装 could + 主语 + 被动原形 be saved。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only after the bell rang ____ talking about the Silk Road.', 'did the class stop', 'the class stopped', 'the class did stop', 'did the class stopped', 'A', 'Only after… 置于句首,倒装 did + 主语 + 原形 stop。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only in recent years ____ to value these forgotten canal towns.', 'people have begun', 'have people begun', 'did people began', 'people began', 'B', 'Only in recent years 置于句首,现在完成倒装,have 提前。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only when you walk the route yourself ____ its true length.', 'you feel', 'you do feel', 'do you feel', 'do you felt', 'C', 'Only when… 置于句首,一般现在倒装 do + 主语 + 原形 feel。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only by working together ____ such a huge canal.', 'the workers could build', 'the workers built', 'could the workers built', 'could the workers build', 'D', 'Only by… 置于句首,倒装 could + 主语 + 原形 build。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only after the museum opened online ____ visit it from home.', 'could people', 'people could', 'did people to', 'people did', 'A', 'Only after… 置于句首,倒装 could + 主语 + 原形 visit。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only then ____ that the old maps were still useful.', 'they discovered', 'did they discover', 'they did discover', 'did they discovered', 'B', 'Only then 置于句首,倒装 did + 主语 + 原形 discover。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only through trade along the Silk Road ____ rich and powerful.', 'many cities grew', 'many cities did grow', 'did many cities grow', 'did many cities grew', 'C', 'Only through… 置于句首,倒装 did + 主语 + 原形 grow。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only if we record these stories ____ remember them.', 'future readers will', 'future readers would to', 'will future readers to', 'will future readers', 'D', 'Only if… 置于句首,倒装 will + 主语 + 原形 remember。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only after a long search ____ the lost section of the canal.', 'did the team find', 'the team found', 'the team did find', 'did the team found', 'A', 'Only after… 置于句首,倒装 did + 主语 + 原形 find。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only here ____ see the oldest part of the ancient waterway.', 'visitors can', 'can visitors', 'visitors could to', 'visitors can to', 'B', 'Only here 置于句首,倒装 can + 主语 + 原形 see。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only when the grain arrived ____ that the canal had saved the city.', 'the people knew', 'the people did know', 'did the people know', 'did the people knew', 'C', 'Only when… 置于句首,倒装 did + 主语 + 原形 know。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.02'), 'Only by reading old records ____ piece together the lost past.', 'scholars can', 'scholars could to', 'scholars can to', 'can scholars', 'D', 'Only by… 置于句首,倒装 can + 主语 + 原形 piece together。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'So important ____ to trade that emperors kept it in good repair.', 'was the canal', 'the canal was', 'the canal is', 'were the canal', 'A', 'So + 形容词 置于句首,主句倒装系动词 was + 主语 the canal。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'Such ____ the fame of the Silk Road that traders came from far away.', 'had', 'was', 'did', 'were', 'B', 'Such + be + 主语 结构;fame 为单数,用 was。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), '____ the engineers known the danger, they would have changed the route.', 'If had', 'Did', 'Had', 'Were', 'C', '虚拟条件省略 if,把 Had 提前构成倒装(=If the engineers had known)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'So heavy ____ the grain boats that they moved very slowly.', 'was', 'did', 'had', 'were', 'D', 'So + 形容词 置于句首,boats 复数用 were。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), '____ it not for the Grand Canal, the northern cities would have suffered.', 'Were', 'Was', 'Had', 'If were', 'A', 'Were it not for… 固定倒装结构(=If it were not for)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'Such ____ his interest in history that he read every book about it.', 'were', 'was', 'did', 'had', 'B', 'Such + be + 主语;interest 为单数,用 was。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), '____ you ever visit Suzhou, you will see the old canal for yourself.', 'Would', 'If should', 'Should', 'Did', 'C', 'Should you… 倒装表示将来可能(=If you should ever visit)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'So well ____ the ancient walls that they still stand today.', 'the walls were built', 'the walls built', 'was the walls built', 'were the walls built', 'D', 'So + 副词 置于句首,被动倒装;walls 复数用 were…built。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), '____ the emperor not moved his capital, the canal might have stayed unused.', 'Had', 'If had', 'Did', 'Were', 'A', '省略 if 的虚拟倒装:Had the emperor not moved…(=If the emperor had not moved)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'So clearly ____ the value of the past that the city saved its old streets.', 'the people saw', 'did the people see', 'the people did see', 'did the people saw', 'B', 'So + 副词 置于句首,主句倒装 did + 主语 + 原形 see。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'Such ____ the crowds at the Forbidden City that tickets sold out early.', 'was', 'did', 'were', 'had', 'C', 'Such + be + 主语;crowds 复数,用 were。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), '____ we known how fragile the relics were, we would have been more careful.', 'If had', 'Did', 'Were', 'Had', 'D', '省略 if 倒装:Had we known…(=If we had known)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'So famous ____ that millions of people visit it every year.', 'is the Forbidden City', 'the Forbidden City is', 'the Forbidden City was', 'are the Forbidden City', 'A', 'So + 形容词 置于句首,现在时倒装 is + 单数主语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), '____ it not for Zhang Qian’s journeys, the trade routes might never have opened.', 'Was', 'Were', 'Had', 'If were', 'B', 'Were it not for… 固定倒装结构。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'So great ____ that the empire could not survive without it.', 'the canal’s value was', 'the canal’s value is', 'was the canal’s value', 'were the canal’s value', 'C', 'So + 形容词 置于句首,倒装 was + 主语 value。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), '____ you wish to learn more, the online museum is open day and night.', 'Would', 'If should', 'Did', 'Should', 'D', 'Should you… 倒装(=If you should wish)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'Such ____ the importance of salt that it became a main source of income.', 'was', 'were', 'did', 'had', 'A', 'Such + be + 主语;importance 为单数,用 was。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'So slowly ____ that repairs took many years to finish.', 'the work went', 'did the work go', 'the work did go', 'did the work went', 'B', 'So + 副词 置于句首,倒装 did + 主语 + 原形 go。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), '____ the canal not been rebuilt, grain could not have reached the north.', 'If had', 'Did', 'Had', 'Were', 'C', '省略 if 倒装:Had the canal not been rebuilt…(=If the canal had not been rebuilt)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U3' AND code='se4u3.03'), 'Such ____ the beauty of the old town that artists came to paint it.', 'were', 'did', 'had', 'was', 'D', 'Such + be + 主语;beauty 为单数,用 was。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Grand Canal', 'The Grand Canal is the longest artificial river ever made by people. Stretching for about 1,800 kilometres, it links several provinces and joins five great river systems, running all the way from Beijing in the north to Hangzhou in the south. The first part was dug long ago, around 486 BCE, when the leader of the State of Wu needed a better way to move grain and military supplies northward. Instead of building roads, he chose a longer-lasting waterway based on natural rivers. Centuries later, Emperor Yang of the Sui dynasty had the old channels rebuilt and connected into one continuous canal. During the Ming dynasty, the canal became the economic lifeline of the empire, and tens of thousands of workers were employed to keep it open. Boats carried grain, salt, cotton and many other goods between the south and the north. Although trains later reduced its importance, the canal is still seen today as a treasure worth protecting.', '说明·大运河的由来与发展', 159, '[{"q":"Why did the leader of the State of Wu first build a canal?","answer":"A","options":["To move supplies to the north more easily.","To attract visitors from other states.","To connect Beijing with Hangzhou at once.","To replace all the rivers in China."],"explanation":"原文 “needed a better way to move grain and military supplies northward” 的转述。"},{"q":"What did Emperor Yang of the Sui dynasty do?","answer":"B","options":["He dug the very first section himself.","He joined the older waterways into one long canal.","He closed the canal to all traders.","He moved the capital to Hangzhou."],"explanation":"原文 “had the old channels rebuilt and connected into one continuous canal” 的转述。"},{"q":"How is the Grand Canal regarded today, according to the text?","answer":"A","options":["As a valuable heritage that should be kept safe.","As a useless and forgotten ditch.","As the busiest trade route in the world.","As a danger that must be filled in."],"explanation":"末句 “still seen today as a treasure worth protecting” 的转述。"}]'::jsonb, '[{"word":"artificial","cn":"人造的"},{"word":"lifeline","cn":"命脉"},{"word":"empire","cn":"帝国"}]'::jsonb, 2, 'elective4', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Forbidden City', 'The Forbidden City, in the heart of Beijing, was the imperial palace of China for almost five hundred years. Built between 1406 and 1420 under the Ming dynasty, it served as the home and workplace of emperors during both the Ming and Qing dynasties. Its name came from the fact that ordinary people were not allowed to enter without permission. The palace is made up of about ninety smaller palaces and many other halls, courtyards and gardens, all carefully arranged according to old ideas of order and balance. After the last emperor left in 1911, the palace slowly opened to the public, and in 1987 it was listed as a World Heritage Site. Today it is one of the most visited museums on earth, welcoming millions of people every year. Visitors come not only to admire its golden roofs and red walls but also to learn how people once lived and ruled. Protecting such a place keeps the memory of history alive.', '说明·故宫的历史与价值', 162, '[{"q":"Why was the palace given the name “Forbidden City”?","answer":"B","options":["It was hidden deep in the mountains.","Common people could not go in without permission.","No emperor ever lived there.","It was always closed in winter."],"explanation":"原文 “ordinary people were not allowed to enter without permission” 的转述。"},{"q":"What happened to the palace after 1911?","answer":"C","options":["It was completely pulled down.","It was turned into a market.","It gradually became open to ordinary visitors.","It became the home of a new emperor."],"explanation":"原文 “the palace slowly opened to the public” 的转述。"},{"q":"Why do people visit the Forbidden City today, according to the text?","answer":"D","options":["To buy cheap modern goods.","To watch trains pass by.","To live inside the old palaces.","To enjoy its beauty and learn about the past."],"explanation":"末段 “admire its golden roofs…learn how people once lived” 的转述。"}]'::jsonb, '[{"word":"imperial","cn":"皇帝的;帝国的"},{"word":"permission","cn":"许可"},{"word":"courtyard","cn":"庭院"}]'::jsonb, 2, 'elective4', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Web of Roads', 'The Silk Road was not a single road but a wide web of routes that crossed China and reached far beyond its borders. It linked cities such as Xi’an and Urumqi and continued westward all the way to Istanbul and Venice. A German geographer first gave these routes their famous name because silk was the most important product carried along them. During the Han dynasty, Emperor Wu sent Zhang Qian on two long missions to the Western Regions, and his travels opened the way for later trade and friendly contact between China and the western states. Along the routes people exchanged not only goods like tea, porcelain and gold but also skills, music, dance and new ideas. Crafts such as raising silkworms and casting iron spread westward, while grapes, walnuts and other plants travelled east into China. In this way the Silk Road became far more than a path for trade; it became a bridge that joined very different cultures together.', '说明·陆上丝绸之路', 161, '[{"q":"Why were these routes called the “Silk Road”?","answer":"A","options":["Silk was the chief good carried along them.","They were paved with silk cloth.","Only silk farmers were allowed on them.","They were built by silk traders alone."],"explanation":"原文 “silk was the most important product carried along them” 的转述。"},{"q":"What was the result of Zhang Qian’s missions?","answer":"B","options":["They ended all contact with the West.","They made later trade and friendship possible.","They closed the western borders.","They stopped the trade in silk."],"explanation":"原文 “opened the way for later trade and friendly contact” 的转述(非照抄)。"},{"q":"Besides goods, what else moved along the Silk Road?","answer":"C","options":["Only soldiers and weapons.","Nothing but silk cloth.","Skills, music and fresh ideas.","Empty boats and carts."],"explanation":"原文 “skills, music, dance and new ideas” 的转述。"}]'::jsonb, '[{"word":"web","cn":"网络"},{"word":"geographer","cn":"地理学家"},{"word":"mission","cn":"使命;出使"}]'::jsonb, 2, 'elective4', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Road Across the Sea', 'While many people picture camels crossing deserts, the Silk Road was not limited to land. Ships also carried trade between China and distant lands, following sea routes that modern scholars call the Maritime Silk Road. Sailing boats left the southern coast of China, passed through the Strait of Malacca in Southeast Asia, and reached destinations as far away as the Indian Peninsula. By sea, traders could move heavy and fragile goods, such as porcelain, more safely than over rough mountain paths. The sea routes connected China with India, Arabia and eventually Europe, allowing an exchange of products, beliefs and knowledge. Coastal cities grew wealthy as their harbours filled with ships from many nations. Like the land routes, the sea routes carried far more than cargo: they spread religions, customs and ways of thinking from one shore to another. Together, the land and sea Silk Roads helped build lasting ties between the East and the West.', '说明·海上丝绸之路', 155, '[{"q":"What do modern scholars call the sea trade routes?","answer":"D","options":["The Grand Canal.","The Mountain Road.","The Desert Path.","The Maritime Silk Road."],"explanation":"原文 “sea routes that modern scholars call the Maritime Silk Road”。"},{"q":"Why was the sea route useful for goods like porcelain?","answer":"A","options":["Fragile items could travel more safely by water.","It was much shorter than any land road.","Porcelain floated easily on the sea.","No taxes were paid at sea."],"explanation":"原文 “move heavy and fragile goods…more safely than over rough mountain paths” 的转述。"},{"q":"How did coastal cities change because of sea trade?","answer":"B","options":["They were left empty and poor.","They became rich as ships filled their harbours.","They moved inland to the mountains.","They stopped trading with anyone."],"explanation":"原文 “Coastal cities grew wealthy as their harbours filled with ships” 的转述。"}]'::jsonb, '[{"word":"fragile","cn":"易碎的"},{"word":"harbour","cn":"港湾"},{"word":"cargo","cn":"货物"}]'::jsonb, 2, 'elective4', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The First Historian', 'Long before China’s canals reached their greatest length, a Greek writer named Herodotus was creating a new kind of book. Written around 440 BCE, his work, known as The Histories, is often called the founding work of history in the Western world. Instead of simply repeating old legends, Herodotus tried to record real events, customs and conflicts among the peoples of Western Asia, North Africa and Greece. He travelled widely, asked many questions and compared different accounts before writing anything down. Because of this careful method, his book became one of the most important sources for understanding the ancient world. More than that, Herodotus showed later writers that the past could be examined in a systematic, careful manner, rather than just remembered through stories. For this reason, many people regard him as the very first historian, and his way of recording the world still shapes how we study history today.', '说明·希罗多德与《历史》', 150, '[{"q":"Why is The Histories an important book?","answer":"C","options":["It was the longest book of its time.","It told only funny stories.","It is seen as the first true work of Western history.","It was written in modern English."],"explanation":"原文 “the founding work of history in the Western world” 的转述。"},{"q":"How did Herodotus gather his information?","answer":"D","options":["He copied one old legend word for word.","He stayed at home and guessed.","He asked only one person.","He travelled, asked questions and compared accounts."],"explanation":"原文 “travelled widely, asked many questions and compared different accounts” 的转述。"},{"q":"What did Herodotus teach later writers?","answer":"A","options":["That history can be studied in an orderly, careful way.","That history should be forgotten.","That stories are always false.","That only kings matter in history."],"explanation":"原文 “the past could be examined in a systematic, careful manner” 的转述。"}]'::jsonb, '[{"word":"legend","cn":"传说"},{"word":"account","cn":"记述;描述"},{"word":"systematic","cn":"系统的"}]'::jsonb, 2, 'elective4', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Worth Keeping', 'Why should we spend money and effort to protect old canals, palaces and city walls? Some people argue that such places are out of date and simply get in the way of modern building. Yet many others believe that historic sites are far too valuable to lose. First, they are a link to our past. A wall built six hundred years ago can tell us how people once lived, worked and defended their homes. Second, old places strengthen a shared sense of who we are. When people from one country visit the same famous site, they feel connected by a common story. Third, historic places can help the economy, because visitors from all over the world travel to see them and spend money nearby. Of course, protecting these sites costs time and money, but the reward is great. Once a piece of history is destroyed, it can never be brought back, so keeping it safe is everyone’s duty.', '议论·为何保护古迹', 158, '[{"q":"What do some people say against protecting old sites?","answer":"B","options":["They are too small to notice.","They are outdated and block new building.","They cost nothing to keep.","They attract too few visitors."],"explanation":"原文 “out of date and simply get in the way of modern building” 的转述。"},{"q":"How can historic places help the economy?","answer":"C","options":["They produce grain for the city.","They lower the price of houses.","Tourists come to visit them and spend money.","They give people free electricity."],"explanation":"原文 “visitors…travel to see them and spend money nearby” 的转述。"},{"q":"Why does the writer say protecting sites is important?","answer":"D","options":["New buildings are always ugly.","Old walls are cheap to repair.","Tourists dislike modern cities.","Lost history can never be recovered."],"explanation":"原文 “Once a piece of history is destroyed, it can never be brought back” 的转述。"}]'::jsonb, '[{"word":"out of date","cn":"过时的"},{"word":"defend","cn":"保卫"},{"word":"reward","cn":"回报"}]'::jsonb, 2, 'elective4', 'U3', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'Marco Polo’s Journey', 'More than seven hundred years ago, a young man named Marco Polo set out from Venice on a long (1)____ to the East. The trip was hard and dangerous, and it took him several (2)____ to reach China. When he finally arrived, he was (3)____ by the size and wealth of the cities he saw. He stayed in China for many years and even (4)____ for the great emperor Kublai Khan. During this time he (5)____ many places that no European had ever seen. When he at last returned home, few people (6)____ his amazing stories. They thought he was simply (7)____ tales. But Marco Polo wrote a (8)____ about his travels, and slowly readers began to (9)____ that the East was real. His book opened a window on a faraway world and (10)____ many later explorers to follow his path.', 141, 2, '[{"q":"1","answer":"A","options":["journey","garden","machine","price"],"explanation":"a long journey 漫长的旅程。"},{"q":"2","answer":"B","options":["metres","years","prices","songs"],"explanation":"several years 好几年(时间)。"},{"q":"3","answer":"C","options":["bored","angry","amazed","afraid"],"explanation":"be amazed by 被……惊到。"},{"q":"4","answer":"D","options":["slept","failed","cried","worked"],"explanation":"worked for the emperor 为皇帝效力。"},{"q":"5","answer":"A","options":["visited","ate","sold","threw"],"explanation":"visited many places 游历许多地方。"},{"q":"6","answer":"B","options":["forgot","believed","lost","broke"],"explanation":"few people believed 很少人相信。"},{"q":"7","answer":"C","options":["cleaning","cooking","making up","washing"],"explanation":"making up tales 编故事。"},{"q":"8","answer":"D","options":["song","price","game","book"],"explanation":"wrote a book 写了一本书。"},{"q":"9","answer":"A","options":["believe","forget","lose","sell"],"explanation":"begin to believe 开始相信。"},{"q":"10","answer":"B","options":["stopped","inspired","frightened","bored"],"explanation":"inspired explorers 激励了探险家。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'Zhang Qian’s Mission', 'During the Han dynasty, the emperor wanted to build (1)____ with the lands to the west of China. He chose a brave official named Zhang Qian to (2)____ this difficult task. Zhang Qian set off with a small group, but on the way he was (3)____ by enemies and held for many years. He never gave (4)____ his mission, however, and at last he managed to escape. When he returned, he brought back (5)____ knowledge about the peoples, animals and goods of the Western Regions. His reports (6)____ the way for regular trade along what later became the Silk Road. Thanks to his (7)____, Chinese silk travelled west while new plants and ideas (8)____ into China. Today many people (9)____ Zhang Qian as a great explorer whose courage (10)____ two parts of the world together.', 135, 2, '[{"q":"1","answer":"C","options":["prices","mistakes","links","games"],"explanation":"build links 建立联系。"},{"q":"2","answer":"D","options":["sleep","lose","sell","handle"],"explanation":"handle this task 处理这项任务。"},{"q":"3","answer":"A","options":["captured","invited","praised","paid"],"explanation":"was captured 被抓获。"},{"q":"4","answer":"B","options":["in","up","on","off"],"explanation":"give up 放弃。"},{"q":"5","answer":"C","options":["empty","silent","valuable","cheap"],"explanation":"valuable knowledge 宝贵的知识。"},{"q":"6","answer":"D","options":["lost","sold","broke","paved"],"explanation":"paved the way 铺平了道路。"},{"q":"7","answer":"A","options":["efforts","prices","noises","songs"],"explanation":"thanks to his efforts 多亏他的努力。"},{"q":"8","answer":"B","options":["stopped","flowed","fell","slept"],"explanation":"ideas flowed into 涌入。"},{"q":"9","answer":"C","options":["forget","lose","regard","sell"],"explanation":"regard…as 把……视为。"},{"q":"10","answer":"D","options":["kept","left","threw","brought"],"explanation":"brought…together 把……连在一起。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'A Museum Online', 'In recent years, technology has changed the way we (1)____ history. Today you do not need to travel far to see a famous (2)____. Many of the world’s greatest museums can now be visited (3)____, right from your own home. A team of experts spent eighteen months building an online museum that (4)____ collections from many countries. Using special cameras, they took photographs so (5)____ that visitors can see every tiny detail of a painting. If you are (6)____ in one of the museums, you simply type its name and start your tour. This kind of project makes art and history (7)____ to everyone, not only to those who can afford to travel. Of course, standing in front of a real (8)____ is still special, but an online visit is a wonderful way to (9)____ from home. Thanks to the internet, the treasures of the past are now within (10)____ of millions of people.', 154, 2, '[{"q":"1","answer":"A","options":["study","eat","sell","throw"],"explanation":"study history 学习历史。"},{"q":"2","answer":"B","options":["garden","museum","market","kitchen"],"explanation":"a famous museum 著名博物馆。"},{"q":"3","answer":"C","options":["loudly","slowly","online","never"],"explanation":"visited online 在线参观。"},{"q":"4","answer":"D","options":["loses","sells","breaks","holds"],"explanation":"holds collections 收藏着藏品。"},{"q":"5","answer":"A","options":["clear","dark","empty","silent"],"explanation":"so clear that 如此清晰。"},{"q":"6","answer":"B","options":["afraid","interested","angry","late"],"explanation":"interested in 对……感兴趣。"},{"q":"7","answer":"C","options":["empty","silent","available","cheap"],"explanation":"available to everyone 人人可及。"},{"q":"8","answer":"D","options":["price","noise","song","painting"],"explanation":"a real painting 真迹画作。"},{"q":"9","answer":"A","options":["learn","sleep","fall","cry"],"explanation":"learn from home 在家学习。"},{"q":"10","answer":"B","options":["price","reach","noise","song"],"explanation":"within reach 触手可及。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'A Trip on the Canal', 'Last summer my family took a boat trip along part of the Grand Canal. As we floated south, our guide (1)____ us about the canal’s long history. She said that for hundreds of years it had been the main (2)____ for moving grain to the north. Along the banks we saw old (3)____ where traders had once stopped to rest. Some of the houses were more than a hundred years (4)____, yet people still lived in them. Although the canal is no longer as (5)____ as it once was, it has not been forgotten. The government has started a huge project to (6)____ water from the south to the dry north, using parts of the old waterway. Seeing the boats and bridges, I (7)____ how clever the ancient builders had been. By the end of the trip, I felt (8)____ of this great work. The canal had (9)____ from a busy trade route into a living piece of history that we can still (10)____ today.', 165, 2, '[{"q":"1","answer":"C","options":["ate","sold","told","threw"],"explanation":"told us about 给我们讲述。"},{"q":"2","answer":"D","options":["price","noise","song","route"],"explanation":"the main route 主要路线。"},{"q":"3","answer":"A","options":["towns","prices","songs","games"],"explanation":"old towns 古镇。"},{"q":"4","answer":"B","options":["new","old","rich","busy"],"explanation":"years old 有……年历史。"},{"q":"5","answer":"C","options":["empty","silent","important","cheap"],"explanation":"as important as 像……一样重要。"},{"q":"6","answer":"D","options":["sell","lose","break","move"],"explanation":"move water 调水。"},{"q":"7","answer":"A","options":["realised","forgot","lost","sold"],"explanation":"realised how clever 意识到多么聪明。"},{"q":"8","answer":"B","options":["afraid","proud","bored","angry"],"explanation":"proud of 为……自豪。"},{"q":"9","answer":"C","options":["stopped","failed","changed","disappeared"],"explanation":"changed from…into 从……变成。"},{"q":"10","answer":"D","options":["forget","lose","sell","enjoy"],"explanation":"still enjoy today 今天仍能欣赏。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'Keep the Old Buildings', 'In many cities, old buildings are being pulled down to make (1)____ for tall new towers. Some people think this is a (2)____ of progress. They say that old houses look out of date and are hard to (3)____ with modern life. Others, however, strongly (4)____ this idea. They believe that historic buildings are a precious (5)____ to our past. An old temple or street can remind us of the people who lived there long (6)____. Such places also bring (7)____ visitors from around the world, which helps the local economy. If we (8)____ down every old building, our cities will all look the same and lose their special (9)____. Once a historic building is gone, it can never be (10)____. For these reasons, many people feel we should protect old buildings instead of destroying them.', 136, 2, '[{"q":"1","answer":"A","options":["room","price","noise","song"],"explanation":"make room for 给……腾地方。"},{"q":"2","answer":"B","options":["price","sign","noise","game"],"explanation":"a sign of progress 进步的标志。"},{"q":"3","answer":"C","options":["sell","throw","fit","lose"],"explanation":"fit with 与……相融。"},{"q":"4","answer":"D","options":["enjoy","forget","sell","oppose"],"explanation":"oppose this idea 反对这种看法。"},{"q":"5","answer":"A","options":["link","price","noise","song"],"explanation":"a link to our past 与过去的纽带。"},{"q":"6","answer":"B","options":["never","ago","slowly","loudly"],"explanation":"long ago 很久以前。"},{"q":"7","answer":"C","options":["silent","empty","many","cheap"],"explanation":"many visitors 许多游客。"},{"q":"8","answer":"D","options":["wash","cook","clean","tear"],"explanation":"tear down 拆除。"},{"q":"9","answer":"A","options":["character","price","noise","song"],"explanation":"special character 独特韵味。"},{"q":"10","answer":"B","options":["sold","rebuilt","cooked","washed"],"explanation":"never be rebuilt 无法重建。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'Goods on the Water', 'During the Ming dynasty, grain was not the only (1)____ carried north along the Grand Canal. Salt was another, and it had become one of the most (2)____ sources of income for the empire. Boats also carried cotton, wool, coal and even precious (3)____ from one region to another. At busy times, more than a hundred thousand soldiers were needed to (4)____ the thousands of government boats on the water. Port cities along the canal grew (5)____, and Suzhou in particular became a thriving centre of trade. Hotels, restaurants and shops opened to (6)____ the many travellers who passed through. In this way, the canal did more than move goods; it helped the whole (7)____ to grow. It also allowed people from the north and south to (8)____ ideas and customs. The canal was truly the (9)____ of the empire, a single waterway on which countless lives and businesses (10)____.', 150, 2, '[{"q":"1","answer":"C","options":["price","noise","product","song"],"explanation":"the only product 唯一的货物。"},{"q":"2","answer":"D","options":["empty","silent","cheap","reliable"],"explanation":"reliable sources 可靠的来源。"},{"q":"3","answer":"A","options":["stones","prices","noises","songs"],"explanation":"precious stones 宝石。"},{"q":"4","answer":"B","options":["sell","operate","forget","lose"],"explanation":"operate the boats 驾驶船只。"},{"q":"5","answer":"C","options":["empty","silent","rich","afraid"],"explanation":"grew rich 变得富裕。"},{"q":"6","answer":"D","options":["break","lose","throw","serve"],"explanation":"serve travellers 服务旅客。"},{"q":"7","answer":"A","options":["economy","price","noise","song"],"explanation":"the whole economy 整个经济。"},{"q":"8","answer":"B","options":["lose","exchange","sell","drop"],"explanation":"exchange ideas 交流思想。"},{"q":"9","answer":"C","options":["price","noise","lifeline","song"],"explanation":"the lifeline 命脉。"},{"q":"10","answer":"D","options":["stopped","failed","disappeared","depended"],"explanation":"lives depended on 生活依赖于。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·对话 A Trip on the Grand Canal', '上外版选择性必修第四册 U3 · dialogue', 3, 'Mia: Dad, where are we going for the trip this weekend?
