INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·短文 Visiting a Historic Site', '上外版选择性必修第四册 U3 · passage', 2, 'Here is a simple tip for anyone visiting a historic site.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Summary of a Claim-Counterclaim Essay(为一篇立论—驳论文写摘要)', 'Should Historical Buildings Be Reconstructed or Removed?', '假设你读了一篇题为《城市里的历史建筑该重建或拆除吗?》的博客。原文认为有丰富文化价值的历史建筑不应被重建或拆除:支持拆除者认为旧建筑过时、难与现代建筑相融,且不翻新会贬值;但作者反驳说旧建筑吸引各国游客、是经济的推动力,还能反映文化、增强民族认同。请用英语写一篇约60词的摘要,做到:① 用自己的话(同义替换、改变句式);② 只保留最重要的观点;③ 保持原文原意、不加入个人评论。', 'You have read a blog titled “Should Historical Buildings in the City Be Reconstructed or Removed?” Write a summary of about 60 words. You should: 1) use your own words (synonyms and changed sentence structures); 2) keep only the most important points; 3) keep the original meaning without adding your own opinion.', '["点明原文主张(有文化价值的历史建筑不应被拆除或重建)","概括赞成拆除一方的理由(过时、难融现代、不翻新会贬值)","概括作者的反驳(吸引游客、推动经济、反映文化、增强认同)","用自己的话改写、不照抄、不加评论"]'::jsonb, 70, 100, 'The blog argues that historical buildings of rich cultural value should be kept rather than rebuilt or pulled down. Some claim such buildings are outdated and hard to fit with modern cities, and that unused ones lose their worth. However, the writer replies that old sites draw tourists, boost the economy, reflect culture and strengthen national identity, so they deserve protection.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["The blog argues that historical buildings of rich cultural value should be kept rather than rebuilt or pulled down.","Some claim such buildings are outdated and hard to fit with modern cities.","The writer replies that old sites draw tourists, boost the economy and reflect culture.","For these reasons, historical buildings deserve to be protected."]'::jsonb, '[{"wrong":"The blog argue that…","correct":"The blog argues that…","note":"主语第三人称单数,动词加 s。"},{"wrong":"Such buildings are hard to fit modern cities.","correct":"Such buildings are hard to fit with modern cities.","note":"fit with sth 与……相融,需介词 with。"},{"wrong":"In a summary, I think old buildings are beautiful.","correct":"The writer believes old buildings are valuable.","note":"摘要不得加入个人评论(I think),应转述原作者观点。"}]'::jsonb, '【立论—驳论文摘要结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective4', 'U3', '{"title":"倒装句·速查(否定前置 / Only+状语 / so·such…that / 虚拟省略)","intro":"倒装就是把正常的「主语+谓语」语序颠倒,用来强调或承前。常见为部分倒装:把助动词/情态动词/be 提到主语前(do/does/did + 主语 + 动词原形;had/have + 主语 + 过去分词)。判断口诀:句首是否定/only/so/such,主句就要倒装;从句不倒装。","table":{"headers":["触发词置于句首","倒装形式 / 例句"],"rows":[["Never / Seldom / Rarely / Little / Hardly…when / No sooner…than","助动词提前:Never had I seen…;No sooner had we left than…"],["Not until + 状语","主句倒装:Not until then did the canal lose its importance."],["Not only…but also…","Not only did it carry grain, but it also spread ideas."],["Only + 副词/介词短语/状语从句","Only then did people realise…;Only by trying can we succeed."],["So + 形/副…that;Such + 名…that","So important was the canal that…;Such was the fame that…"],["虚拟条件省略 if","Had I known…;Were it not for…;Should you visit…"]]},"specialRules":[{"rule":"部分倒装只动助动词/情态/be,实义动词留原位、用原形","mark":"Only then did people realise(realise 用原形)"},{"rule":"Not only A but also B:倒装只发生在 A(句首)部分,B 不倒装","mark":"Not only did it…, but it also proved…"},{"rule":"so…that 提前的是形容词/副词;such…that 提前的是名词词组","mark":"So heavy were the boats…/ Such was his interest…"},{"rule":"虚拟条件省略 if 时把 had/were/should 提前;否定 not 留在主语后","mark":"Had the emperor not moved…(=If the emperor had not moved)"}],"why":["英语把信息焦点放句尾;当强调成分(否定词、only、so/such)被提到句首时,只能靠倒装助动词来维持句子节奏并表强调,所以主语后才出现真正的谓语。"],"gaokaoPoints":["否定/半否定词置于句首必倒装(never/seldom/hardly/no sooner/not until/not only…);判断助动词时态与主谓一致是采分点。","Only + 状语 在句首使「主句」倒装,而非 only 后面的从句:Only when…did + 主语。","虚拟条件省略 if 的倒装(Had/Were/Should)是写作高分句型,常考语法填空与改错。"],"examVsReal":[{"exam":"Never had I seen such a sight.(考试/书面强调)","real":"I had never seen anything like it.","note":"日常口语多用正常语序;倒装更书面、更强调。"},{"exam":"Had I known, I would have come.(考试虚拟倒装)","real":"If I’d known, I would’ve come.","note":"口语保留 if、用缩略;倒装省 if 更正式。"}]}'::jsonb, 'sufe');
